SELECT username AS user_handle, email AS contact_email FROM users;

UPDATE users 
SET role = 'senior_developer', updated_at = CURRENT_TIMESTAMP 
WHERE user_id = 42;

DELETE FROM users 
WHERE is_active = FALSE AND last_login < '2025-01-01';

CREATE INDEX idx_orders_user_date 
ON orders (user_id, order_date DESC);

-- Inspect index utilization with EXPLAIN
EXPLAIN SELECT * FROM orders WHERE user_id = 42 ORDER BY order_date DESC;

